def transform(grid):
    H = len(grid)
    W = len(grid[0])

    def neighbors(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < H:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < W:
            yield r, c + 1

    def comp(start, color):
        sr, sc = start
        cells = [(sr, sc)]
        seen = {(sr, sc)}
        q = [(sr, sc)]
        while q:
            r, c = q.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in seen and 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color:
                    seen.add((nr, nc))
                    cells.append((nr, nc))
                    q.append((nr, nc))
        return cells

    def boundary(cells):
        b = set(cells)
        res = []
        for r, c in cells:
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in b:
                    res.append((nr, nc))
        return res

    def holes(cells):
        b = set(cells)
        visited = set()
        cnt = 0
        for r, c in boundary(cells):
            if (r, c) not in visited and grid[r][c] == 0:
                q = [(r, c)]
                visited.add((r, c))
                outside = False
                while q:
                    x, y = q.pop()
                    if x == 0 or x == H - 1 or y == 0 or y == W - 1:
                        outside = True
                    for nx, ny in neighbors(x, y):
                        if (nx, ny) not in visited and 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
                            visited.add((nx, ny))
                            q.append((nx, ny))
                if not outside:
                    cnt += 1
        return cnt

    # Identify separator: connected component(s) of 1 that touch the border.
    seen1 = set()
    sep = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1 and (r, c) not in seen1:
                cells = comp((r, c), 1)
                seen1.update(cells)
                if any(rr == 0 or rr == H - 1 or cc == 0 or cc == W - 1 for rr, cc in cells):
                    sep.update(cells)

    # Learn mapping: non-background, non-5, non-separator components.
    mapping = {}
    seenp = set(sep)
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0 and v != 5 and (r, c) not in seenp:
                cells = comp((r, c), v)
                seenp.update(cells)
                mapping[holes(cells)] = v

    # Recolor 5 components.
    out = [row[:] for row in grid]
    seen5 = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 5 and (r, c) not in seen5:
                cells = comp((r, c), 5)
                seen5.update(cells)
                col = mapping.get(holes(cells), 1)
                for rr, cc in cells:
                    out[rr][cc] = col
    return out
